def compute(vars):
    old_cost = vars["v1"]
    new_cost = vars["v2"]

    if old_cost == 0:
        return None

    change = new_cost - old_cost
    change_ratio = change / old_cost
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_cost": old_cost,
            "new_cost": new_cost,
            "change": change,
            "change_ratio": change_ratio,
            "percentage_change": percentage_change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
